package org.sleepwell.app;
import android.content.Context;import android.net.Uri;import java.util.*;import java.util.concurrent.*;import java.util.concurrent.atomic.AtomicBoolean;
/** Retained local diary operations and bounded provider export, all off the main thread. */
final class DiaryJobs {
 static final Map<DiaryStore.Factory,Job> jobs=new IdentityHashMap<>();static synchronized Job get(Context c){DiaryStore.Factory factory=DiaryStore.factory;return jobs.computeIfAbsent(factory,k->new Job(c.getApplicationContext(),factory));}
 static final class State{final boolean busy;final List<DiaryStore.Entry> rows;final int page,total;final String result,error,saved;State(boolean busy,List<DiaryStore.Entry> rows,int page,int total,String result,String error,String saved){this.busy=busy;this.rows=List.copyOf(rows);this.page=page;this.total=total;this.result=result;this.error=error;this.saved=saved;}}
 interface Action{String run(DiaryStore store)throws Exception;}
 static final class Job{final Context app;final DiaryStore.Factory factory;final ExecutorService worker=Executors.newSingleThreadExecutor();final AtomicBoolean cancelled=new AtomicBoolean();volatile boolean exporting;volatile State state=new State(false,List.of(),0,0,"","","");Job(Context c,DiaryStore.Factory f){app=c;factory=f;}synchronized void start(int page,Action action,String result){if(state.busy)return;cancelled.set(false);State old=state;state=new State(true,old.rows,old.page,old.total,old.result,"","");worker.execute(()->{List<DiaryStore.Entry> rows=old.rows;int total=old.total,selectedPage=page;String saved="",error="";try(DiaryStore store=factory.open(app)){if(action!=null)saved=action.run(store);total=store.count();selectedPage=Math.max(0,Math.min(page,Math.max(0,(total-1)/200)));rows=store.entries(200,selectedPage*200);}catch(Exception failure){error=failure.getMessage()==null?"Diary operation could not finish.":failure.getMessage();}exporting=false;state=new State(false,rows,selectedPage,total,error.isEmpty()?result:old.result,error,saved==null?"":saved);});}void inspect(int page){start(page,null,state.result);}void save(String id,long updated,String title,String text){start(state.page,store->store.save(id,updated,title,text,System.currentTimeMillis()),"Diary entry saved.");}void delete(String id,long updated){start(state.page,store->{store.delete(id,updated);return "";},"Diary entry deleted.");}void export(Uri uri){if(state.busy)return;exporting=true;start(state.page,store->{byte[] bytes=store.export();if(cancelled.get())throw new CancellationException("Export cancelled before writing.");try(java.io.OutputStream output=app.getContentResolver().openOutputStream(uri,"wt")){if(output==null)throw new java.io.IOException("The document provider did not open the diary export.");for(int at=0;at<bytes.length;at+=4096){if(cancelled.get())throw new CancellationException("Export cancelled. The document may contain partial data.");output.write(bytes,at,Math.min(4096,bytes.length-at));}output.flush();}return "";},"Diary JSON exported. It contains private text.");}}
 static void drain(DiaryStore.Factory factory)throws Exception{Job job;synchronized(DiaryJobs.class){job=jobs.get(factory);}if(job!=null)job.worker.submit(()->{}).get(10,TimeUnit.SECONDS);}static synchronized void forget(DiaryStore.Factory factory){Job job=jobs.get(factory);if(job!=null){if(job.state.busy)throw new IllegalStateException("Diary work is active");jobs.remove(factory);job.worker.shutdown();}}
 private DiaryJobs(){}
}
